using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class CleanPresentationTests {
  GameRuntime game;string directory;const string Output="/tmp/idle-clean-ui-review";
  [UnitySetUp]public IEnumerator Setup(){directory=Path.Combine(Path.GetTempPath(),"clean-ui-"+Guid.NewGuid());Directory.CreateDirectory(directory);Directory.CreateDirectory(Output);GameRuntime.SavePathOverride=Path.Combine(directory,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Hardware[0]=4;n.Credits=n.Data=ScientificNumber.From(10000);n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.tutorial="skipped";return n;});Debug.Log("PREPARED_UI_REVIEW: temporary isolated save; runtime diagnostic flag retained, no test footer");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  [UnityTest]public IEnumerator AutomaticSaveAndCompactConnectedViews(){var before=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);yield return new WaitForSecondsRealtime(6);var after=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(after.Writable,Is.True);Assert.That(after.State.SavedAt,Is.GreaterThan(before.State.SavedAt));Assert.That(after.State.Credits.CompareTo(before.State.Credits),Is.GreaterThan(0));Assert.That(game.Status.transform.parent.gameObject.activeSelf,Is.False);Assert.That(game.Status.text,Does.Not.Contain("PREPARED"));foreach(string language in new[]{"de","en"})foreach(int width in new[]{320,390,430}){game.Act(s=>SettingsRules.Change(s,"language",language));PortraitGameView.Set(width,width==320?694:width==390?846:932);game.Show("hardware");yield return null;yield return null;Canvas.ForceUpdateCanvases();var train=game.GetComponent<MobileShell>().Laboratory.Train;Assert.That(train.GetComponent<Image>().sprite,Is.EqualTo(GameTheme.GoldButton));Assert.That(((RectTransform)train.transform).rect.height,Is.EqualTo(44).Within(.1));Assert.That(((RectTransform)train.transform).rect.width,Is.EqualTo(104).Within(.1));WorkshopTests.Capture(width,Screen.height,Output+"/labor-"+language+"-"+width+".png");game.Show("research");yield return null;Canvas.ForceUpdateCanvases();foreach(var card in game.Content.GetComponentsInChildren<LearningCard>())Assert.That(card.Card.Icon.sprite,Is.Not.EqualTo(card.DataIcon.sprite));WorkshopTests.Capture(width,Screen.height,Output+"/research-"+language+"-"+width+".png");}}
  [UnityTest]public IEnumerator EqualVisibleSocketsAndDynamicUniversals(){foreach(string language in new[]{"de","en"})foreach(int width in new[]{320,390,430}){game.Act(s=>SettingsRules.Change(s,"language",language));PortraitGameView.Set(width,width==320?694:width==390?846:932);game.Show("items");yield return null;game.WorkshopView.ChangeMode("inventory");yield return null;Canvas.ForceUpdateCanvases();var display=UnityEngine.Object.FindFirstObjectByType<ModelLoadout>();Assert.That(display.Universal.gameObject.activeSelf,Is.False);var sockets=display.Network.GetComponentsInChildren<ItemPortrait>();Assert.That(sockets.Length,Is.EqualTo(6));foreach(var socket in sockets){Assert.That(((RectTransform)socket.transform).rect.size,Is.EqualTo(Vector2.one*88));var mesh=socket.Frame.canvasRenderer.GetMesh();Assert.That(mesh.bounds.size.x,Is.EqualTo(82).Within(3));Assert.That(mesh.bounds.size.y,Is.EqualTo(82).Within(3));}WorkshopTests.Capture(width,Screen.height,Output+"/slots-locked-"+language+"-"+width+".png");}
   game.Act(s=>{var n=s.Copy();n.Meta.models[9]=(int)ItemBalance.ModelSlotLevel;return MetaRules.Select(n,"K10");});yield return new WaitForSecondsRealtime(.2f);var unlocked=UnityEngine.Object.FindFirstObjectByType<ModelLoadout>();Assert.That(unlocked.Universal.GetComponentsInChildren<ItemPortrait>().Length,Is.EqualTo(2));foreach(var p in unlocked.Universal.GetComponentsInChildren<ItemPortrait>())Assert.That(((RectTransform)p.transform).rect.size,Is.EqualTo(Vector2.one*88));WorkshopTests.Capture(390,846,Output+"/universal-unlocked.png");game.Act(s=>MetaRules.Select(s,""));yield return new WaitForSecondsRealtime(.2f);Assert.That(UnityEngine.Object.FindFirstObjectByType<ModelLoadout>().Universal.gameObject.activeSelf,Is.False);}
  [UnityTest]public IEnumerator ReloadedPrestigeMiraTextFitsItsBubble(){foreach(string language in new[]{"de","en"})foreach(int width in new[]{320,390,430}){game.Act(s=>SettingsRules.Change(s,"language",language));game.Act(s=>NarrativeBridge.Action(s,"reopen","prestige-ready"));PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();yield return new WaitForSecondsRealtime(.2f);Canvas.ForceUpdateCanvases();var coach=UnityEngine.Object.FindFirstObjectByType<MiraCoach>();Assert.That(coach,Is.Not.Null);WorkshopTests.Capture(width,Screen.height,Output+"/mira-prestige-"+language+"-"+width+".png");Assert.That(coach.Speech.preferredHeight,Is.LessThanOrEqualTo(coach.Speech.rectTransform.rect.height+1),"Entire current Mira page must fit after reload: "+coach.Speech.text);Assert.That(game.State.Story.open,Is.EqualTo("prestige-ready"),"Layout must never advance the story");}}

 }
}
